Launching a token sale for your Defi project involves several steps, including setting up a private sale (often referred to as a "pre-sale") and then making the token available on a launchpad or public sale. Here’s how you can structure this process using smart contracts:

### 1. Pre-Sale Contract

A pre-sale contract is useful for managing the private sale of tokens. This contract will handle the following aspects:

- **Token Sale Logic**: Implement the logic for accepting payments in exchange for tokens.
- **Whitelist**: Ensure that only approved addresses (early investors) can participate in the pre-sale.
- **Token Allocation**: Distribute tokens based on the amount paid.
- **Payment Handling**: Manage the receipt and transfer of funds securely.

Here's a simplified example of what a pre-sale contract might look like in Solidity:

```solidity
pragma solidity ^0.8.0;

contract PreSale {
    address payable public owner;
    uint256 public startTime;
    uint256 public endTime;
    uint256 public pricePerToken;
    uint256 public totalTokensForSale;
    mapping(address => uint256) public balances;

    event TokenPurchase(address indexed purchaser, uint256 value, uint256 amount);

    constructor(uint256 _startTime, uint256 _endTime, uint256 _pricePerToken, uint256 _totalTokensForSale) {
        require(_startTime >= block.timestamp, "Start time must be in the past");
        require(_endTime > _startTime, "End time must be after start time");
        require(_pricePerToken > 0, "Price per token must be greater than zero");
        require(_totalTokensForSale > 0, "Total tokens for sale must be greater than zero");

        owner = payable(msg.sender);
        startTime = _startTime;
        endTime = _endTime;
        pricePerToken = _pricePerToken;
        totalTokensForSale = _totalTokensForSale;
    }

    function buyTokens() external payable {
        require(block.timestamp >= startTime && block.timestamp <= endTime, "Sale is not active");
        require(msg.value / pricePerToken >= 1, "Insufficient ETH sent for purchase");

        uint256 tokensToBuy = msg.value / pricePerToken;
        require(tokensToBuy <= totalTokensForSale, "Not enough tokens for sale");

        balances[msg.sender] += tokensToBuy;
        totalTokensForSale -= tokensToBuy;

        emit TokenPurchase(msg.sender, msg.value, tokensToBuy);

        // Transfer tokens to buyer
        address(this).transfer(msg.value);
    }

    function withdrawFunds() external {
        require(msg.sender == owner, "Only the owner can withdraw funds");
        require(address(this).balance > 0, "No funds to withdraw");

        owner.transfer(address(this).balance);
    }
}
```

### 2. Main Contract

The main contract will manage the token itself and any additional functionalities related to the Defi project. It should interact with the pre-sale contract to distribute tokens to buyers.

Here's an example of a main contract:

```solidity
pragma solidity ^0.8.0;

import "./PreSale.sol";

contract MyDefiToken is PreSale {
    string public name = "MyDefiToken";
    string public symbol = "MDT";
    uint8 public decimals = 18;

    constructor() PreSale(0, 3600, 10 ether, 100000000000000000000000000) {}

    function mint(address _to, uint256 _amount) external {
        require(msg.sender == owner, "Only the owner can mint tokens");
        balances[_to] += _amount;
    }

    function burn(address _from, uint256 _amount) external {
        require(msg.sender == owner, "Only the owner can burn tokens");
        balances[_from] -= _amount;
    }

    function transfer(address _to, uint256 _amount) external returns (bool success) {
        require(balances[msg.sender] >= _amount, "Insufficient balance");
        balances[msg.sender] -= _amount;
        balances[_to] += _amount;
        emit Transfer(msg.sender, _to, _amount);
        return true;
    }

    function transferFrom(address _from, address _to, uint256 _amount) external returns (bool success) {
        require(balances[_from] >= _amount, "Insufficient balance");
        require(balances[_to] + _amount <= balances[_from], "Recipient exceeds balance");
        balances[_from] -= _amount;
        balances[_to] += _amount;
        emit Transfer(_from, _to, _amount);
        return true;
    }
}
```

### 3. Launchpad Integration

Once the pre-sale is complete, you can integrate the tokens into a launchpad. A launchpad typically allows users to buy tokens directly from the contract without needing to go through a pre-sale. The launchpad contract would interact with your main contract to facilitate token sales.

Here's a simplified example of a launchpad contract:

```solidity
pragma solidity ^0.8.0;

import "./MyDefiToken.sol";

contract Launchpad {
    MyDefiToken public tokenContract;

    constructor(address _tokenAddress) {
        tokenContract = MyDefiToken(_tokenAddress);
    }

    function buyTokens() external payable {
        require(msg.value / tokenContract.pricePerToken() >= 1, "Insufficient ETH sent for purchase");
        uint256 tokensToBuy = msg.value / tokenContract.pricePerToken();
        require(tokenContract.balances[msg.sender] + tokensToBuy <= tokenContract.totalSupply(), "Exceeds balance");

        tokenContract.burn(msg.sender, tokensToBuy);
        tokenContract.mint(msg.sender, tokensToBuy);
    }
}
```

### Summary

- **Pre-Sale Contract**: Manages the private sale of tokens, ensuring only approved addresses can participate.
- **Main Contract**: Handles the token logic, minting, burning, and transferring tokens.
- **Launchpad Contract**: Facilitates public token sales by interacting with the main contract.

By structuring your contracts this way, you ensure a secure and transparent token sale process. Make sure to thoroughly test each contract and consider security best practices.

